import {ownRecord,denseValues} from './state-validation.mjs';
export const partsActivity={id:'number-parts',stage:'5y',key:'5y:number-parts',area:'Matemáticas',type:'digital',kind:'interactive',label:'6–8 años · con adulto',unit:'Un número, varias formas',title:'Componer y descomponer cantidades',copy:'Reparte las mismas fichas de otra manera. Compara tus dos formas.',goal:'Representar una cantidad en dos partes, comparar formas equivalentes y probar con una cantidad nueva.',duration:'Una exploración breve · sin reloj',support:'Un adulto puede leer una frase cada vez; puedes señalar para que pulse',transfer:'Dibuja siete puntos grandes en papel. Rodéalos en dos grupos de dos maneras distintas. Puedes dejar un grupo vacío. Cuenta los mismos siete puntos en cada dibujo; no necesitas objetos pequeños.'};
export const partsTotals=[6,8];
const draft=()=>({counts:[0,0],reference:null,checked:false,undo:null});
export const newParts=()=>({page:'guide',round:0,rounds:[draft(),null]});
const clonePair=p=>p?[...p]:null;
const snapshot=r=>({counts:[...r.counts],reference:clonePair(r.reference),checked:r.checked});
function pair(value,total){const p=denseValues(value,Array.from({length:total+1},(_,i)=>i),2,true);if(p[0]+p[1]>total)throw Error('Too many parts');return p;}
function version(raw,total){ownRecord(raw,['counts','reference','checked']);if(typeof raw.checked!=='boolean')throw Error('Invalid review');return {counts:pair(raw.counts,total),reference:raw.reference===null?null:pair(raw.reference,total),checked:raw.checked};}
export function validateParts(raw){
 ownRecord(raw,['page','round','rounds']);
 if(!['guide','play','close'].includes(raw.page)||![0,1].includes(raw.round))throw Error('Invalid parts page');
 const a=raw.rounds;if(!Array.isArray(a)||Object.getPrototypeOf(a)!==Array.prototype||a.length!==2||Reflect.ownKeys(a).length!==3)throw Error('Invalid parts rounds');
 const ds=Object.getOwnPropertyDescriptors(a);if([0,1].some(i=>!ds[i]||!Object.hasOwn(ds[i],'value')))throw Error('Invalid round descriptor');
 const rounds=a.map((r,i)=>{if(r===null)return null;ownRecord(r,['counts','reference','checked','undo']);const v=version({counts:r.counts,reference:r.reference,checked:r.checked},partsTotals[i]);return {...v,undo:r.undo===null?null:version(r.undo,partsTotals[i])}});
 if(!rounds[0]||!rounds[raw.round])throw Error('Missing parts round');
 if(raw.page==='guide'&&(raw.round!==0||rounds[1]||rounds[0].counts.some(Boolean)||rounds[0].reference||rounds[0].checked||rounds[0].undo))throw Error('Inconsistent guide');
 return {page:raw.page,round:raw.round,rounds};
}
export function partsResult(s){const r=s.rounds[s.round],total=partsTotals[s.round],sum=r.counts[0]+r.counts[1],previous=r.reference?r.reference[0]+r.reference[1]:null,samePair=!!r.reference&&r.counts.every((n,i)=>n===r.reference[i]),swappedPair=!!r.reference&&!samePair&&r.counts[0]===r.reference[1]&&r.counts[1]===r.reference[0];return {total,sum,reserve:total-sum,previous,equal:previous!==null&&sum===previous,samePair,swappedPair,newDecomposition:!!r.reference&&!samePair&&!swappedPair,complete:sum===total&&previous===total};}
export function editParts(s,part,delta){if(s.page!=='play'||![0,1].includes(part)||![-1,1].includes(delta))return false;const r=s.rounds[s.round];if(delta===1&&!partsResult(s).reserve||delta===-1&&!r.counts[part])return false;r.undo=snapshot(r);r.counts[part]+=delta;r.checked=false;return true;}
export function transferPart(s,from){if(s.page!=='play'||![0,1].includes(from))return false;const r=s.rounds[s.round];if(!r.counts[from])return false;r.undo=snapshot(r);r.counts[from]--;r.counts[1-from]++;r.checked=false;return true;}
export function keepParts(s){if(s.page!=='play')return false;const r=s.rounds[s.round];if(r.reference&&r.reference.every((n,i)=>n===r.counts[i]))return false;r.undo=snapshot(r);r.reference=[...r.counts];r.checked=false;return true;}
export function undoParts(s){const r=s.rounds[s.round];if(s.page!=='play'||!r.undo)return false;Object.assign(r,r.undo,{counts:[...r.undo.counts],reference:clonePair(r.undo.reference),undo:null});return true;}
export function visitParts(s,direction){if(s.page!=='play'||![-1,1].includes(direction)||s.round+direction<0||s.round+direction>1)return false;const next=s.round+direction;if(!s.rounds[next])s.rounds[next]=draft();s.round=next;return true;}
const sumText=p=>`${p[0]} + ${p[1]}`;
export function partsFeedback(s){const r=s.rounds[s.round],v=partsResult(s);let text=`${sumText(r.counts)} son ${v.sum}. `;if(v.reserve)text+=`Quedan ${v.reserve} en la reserva: aún no están las ${v.total} en las dos partes. `;else text+=`Están las ${v.total} en las dos partes. `;if(!r.reference)return text+'Puedes conservar esta forma y probar otra.';text+=`El registro anterior suma ${v.previous}. `;if(v.equal)text+='Las dos sumas representan la misma cantidad. ';else text+='Las dos sumas representan cantidades distintas. ';if(v.complete&&v.newDecomposition)text+=`Has cambiado las cantidades de las partes. Son dos formas completas de ${v.total}, con la misma cantidad en total.`;else if(v.complete&&v.swappedPair)text+='Intercambiaste las mismas dos cantidades de parte. Es un intercambio, no una pareja nueva.';else if(v.complete)text+='Conservaste las mismas cantidades en las partes. Puedes pasar una ficha para explorar otra distribución.';if(!v.complete&&v.reserve)text+=`El reparto actual está incompleto: quedan ${v.reserve} fichas por colocar, fuera de A y B. `;if(v.previous!==null&&v.previous<v.total)text+='El reparto del dibujo anterior también estaba incompleto: tenía fichas por colocar. ';return text;}
const dots=n=>`<span class="parts-dots" aria-hidden="true">${Array.from({length:n},()=>'<span class="parts-token"></span>').join('')}</span>`;
const view=(counts,total)=>`<div class="parts-reference-groups">${counts.map((n,i)=>`<div><strong>Parte ${i?'B':'A'}: ${n}</strong>${dots(n)}${!n?'<span class="quiet">Vacía: cero fichas</span>':''}</div>`).join('')}</div><p>${sumText(counts)} = ${counts[0]+counts[1]} · Reserva: ${total-counts[0]-counts[1]}</p>`;
export function renderParts(root,state,{finish}){
 const s=state.numberParts??=newParts(),r=s.rounds[s.round],v=partsResult(s);
 const redraw=selector=>{renderParts(root,state,{finish});root.querySelector(selector)?.focus();};
 root.innerHTML=`<section class="number-parts" aria-labelledby="parts-title"><p class="eyebrow">6–8 años · con un adulto para leer si hace falta</p><h4 id="parts-title" tabindex="-1">Un número, varias formas</h4>${s.page==='guide'?`<p>Tenemos seis fichas iguales.</p><p>Haz dos partes. Conserva tu forma.</p><p>Muévelas y mira qué cambia.</p><div class="parts-example" aria-label="Ejemplo: 1 más 3 son 4, otra cantidad">${view([1,3],4)}</div><p>El ejemplo muestra cuatro. Tú probarás con seis.</p><button type="button" class="action primary" id="parts-start">Quiero repartir seis</button>`:s.page==='close'?`<h5>Tus formas quedan aquí</h5>${s.rounds.map((x,i)=>x?`<article class="parts-reference"><h5>Con ${partsTotals[i]} fichas</h5>${view(x.counts,partsTotals[i])}<p>${x.reference?'Conservaste otra forma: '+sumText(x.reference)+' = '+(x.reference[0]+x.reference[1])+'.':'No conservaste una forma para comparar.'}</p></article>`:'').join('')}<p><strong>Otro reto en papel:</strong> dibuja siete puntos. Haz dos grupos. Dibuja otra forma con los mismos siete. Puede haber un grupo vacío.</p><p>Un adulto puede leer, dibujar o señalar contigo. No hace falta entregar una respuesta.</p><div class="controls"><button type="button" class="action secondary" id="parts-revisit">Volver a mis fichas</button><button type="button" class="action primary" id="parts-finish">Terminar por hoy</button></div>`:`<h5>Ahora: ${v.total} fichas</h5><p>${s.round?'Ahora tienes ocho: a las seis de la primera ronda se han añadido dos fichas nuevas. La colección empieza aquí, sin una forma resuelta para copiar.':'Reparte las seis fichas en dos partes.'}</p><p><strong>Conserva una forma. Prueba otra.</strong></p>${s.round?`<aside class="parts-bridge" aria-label="De seis a ocho fichas"><h5>Seis fichas y llegan dos nuevas</h5><div class="parts-bridge-groups"><div><strong>Antes</strong>${dots(6)}<span>6 fichas</span></div><span aria-hidden="true">+</span><div><strong>Nuevas</strong>${dots(2)}<span>2 fichas</span></div><span aria-hidden="true">=</span><div><strong>Ahora</strong>${dots(8)}<span>8 fichas</span></div></div><p>Añadir las dos fichas cambia el total de seis a ocho. Mover una entre A y B cambia las partes, pero no añade fichas.</p></aside>`:''}<div class="parts-reserve"><strong>Reserva: ${v.reserve}</strong>${dots(v.reserve)}<span>${v.reserve?'Estas fichas aún no están en las partes.':'La reserva está vacía.'}</span></div><div class="parts-groups">${r.counts.map((n,i)=>`<article><h5>Parte ${i?'B':'A'}: ${n}</h5><div class="parts-tray">${dots(n)}${!n?'<span>Vacía: cero</span>':''}</div><button type="button" class="action primary" data-parts-add="${i}" aria-label="Añadir una ficha de la reserva a la parte ${i?'B':'A'}" ${v.reserve?'':'disabled'}>Añadir una ＋</button><button type="button" class="action secondary" data-parts-remove="${i}" aria-label="Devolver una ficha de la parte ${i?'B':'A'} a la reserva" ${n?'':'disabled'}>Devolver una −</button></article>`).join('')}</div><div class="controls parts-transfer">${[0,1].map(i=>`<button type="button" class="action secondary" data-parts-transfer="${i}" ${r.counts[i]?'':'disabled'}>Pasar una de ${i?'B a A':'A a B'}</button>`).join('')}</div><p class="parts-equation" aria-label="${r.counts[0]} más ${r.counts[1]} es igual a ${v.sum}">${sumText(r.counts)} = ${v.sum}</p><div class="controls"><button type="button" class="action primary" id="parts-keep">Conservar esta forma</button><button type="button" class="action secondary" id="parts-undo" ${r.undo?'':'disabled'}>Deshacer último cambio</button></div>${r.reference?`<article class="parts-reference"><h5>Así lo hice antes</h5><p>Este dibujo recuerda otra forma; no son fichas nuevas.</p>${view(r.reference,v.total)}${r.checked?`<p class="parts-equality">${sumText(r.reference)} ${v.equal?'=':'≠'} ${sumText(r.counts)}<span>${v.equal?'Las sumas representan la misma cantidad.':'Las sumas representan cantidades distintas.'}</span></p>`:'<p>La comparación todavía está por hacer.</p>'}</article>`:'<p>«Conservar» deja una imagen para comparar. Puedes conservarla aunque falten fichas por repartir.</p>'}<div class="controls"><button type="button" class="action primary" id="parts-check">Comparar mis formas</button><button type="button" class="action secondary" id="parts-hint">Una pista</button></div><p id="parts-feedback" role="status" tabindex="-1">${r.checked?partsFeedback(s):''}</p><nav class="controls" aria-label="Exploraciones de cantidades"><button type="button" class="action secondary" id="parts-round">${s.round?'Volver a mis seis':'Probar con ocho'}</button><button type="button" class="action secondary" id="parts-close">Llevar la idea al papel</button></nav>`}<details><summary>Una ayuda para acompañar</summary><p>Lee una frase y espera. Puede señalar y otra persona pulsar. Al contar una bandeja, señala cada ficha una vez; las fichas de esa bandeja son iguales. Cero significa que esa parte está vacía.</p><p>Pasar una ficha de A a B cambia las partes, pero no añade fichas. El signo = dice «la misma cantidad»; no significa que los repartos deban ser iguales. La reserva no entra en la suma de las dos partes.</p><p>La imagen guardada es otra versión del mismo conjunto, no se suma a la actual. «Conservar» puede reemplazarla; «Deshacer» recupera el último cambio de esta ronda. Al abrir ocho, aparece una colección nueva, sin un reparto para copiar. El texto recuerda que se han añadido dos fichas a las seis. Cada ronda conserva después su propio borrador.</p><p>No hay puntos, tiempo obligatorio ni orden que superar. Puedes cambiar de ronda, pausar o terminar sin completar las formas. Esto no acredita dominio matemático.</p></details><p class="quiet">Puedes pausar o terminar arriba.</p></section>`;
 const on=(id,fn)=>root.querySelector('#'+id)?.addEventListener('click',fn);
 on('parts-start',()=>{s.page='play';redraw('#parts-title')});on('parts-keep',()=>{keepParts(s);redraw('#parts-keep')});on('parts-undo',()=>{undoParts(s);redraw('#parts-title')});
 for(const [attr,delta] of [['add',1],['remove',-1]])root.querySelectorAll(`[data-parts-${attr}]`).forEach(b=>b.onclick=()=>{const i=Number(b.dataset[attr==='add'?'partsAdd':'partsRemove']);editParts(s,i,delta);renderParts(root,state,{finish});const same=root.querySelector(`[data-parts-${attr}="${i}"]`);(same.disabled?root.querySelector(`[data-parts-${attr==='add'?'remove':'add'}="${i}"]`):same).focus();root.querySelector('#parts-feedback').textContent=`Parte A: ${r.counts[0]}. Parte B: ${r.counts[1]}. Reserva: ${partsResult(s).reserve}.`;});
 root.querySelectorAll('[data-parts-transfer]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.partsTransfer);transferPart(s,i);renderParts(root,state,{finish});const same=root.querySelector(`[data-parts-transfer="${i}"]`);(same.disabled?root.querySelector(`[data-parts-transfer="${1-i}"]`):same).focus();root.querySelector('#parts-feedback').textContent=`Parte A: ${r.counts[0]}. Parte B: ${r.counts[1]}. Reserva: ${partsResult(s).reserve}.`;});
 on('parts-check',()=>{r.checked=true;redraw('#parts-feedback')});on('parts-hint',()=>{const f=root.querySelector('#parts-feedback');f.textContent=v.reserve?'Mira la reserva. Puedes añadir sus fichas a cualquiera de las dos partes.':'Prueba a pasar una ficha a la otra parte. ¿Cambian las partes? ¿Cambia el total?';f.focus()});
 on('parts-round',()=>{visitParts(s,s.round?-1:1);redraw('#parts-title')});on('parts-close',()=>{s.page='close';redraw('#parts-title')});on('parts-revisit',()=>{s.page='play';redraw('#parts-title')});on('parts-finish',finish);
}
